const blueprints: Blueprint[] = [
  b({ id: 'wic-01', skillId: 'words-in-context', domain: 'craft-structure', difficulty: 1, stimulus: 'The city archive had long been difficult to use because its catalog was incomplete. After two years of careful indexing, however, the collection became far more ____ to researchers.', prompt: 'Which choice completes the text with the most logical and precise word or phrase?', choices: ['accessible', 'ancient', 'profitable', 'fragile'], answer: 0, explanation: 'The indexing made the archive easier for researchers to use, so accessible is the precise completion.', traps: ['Supported', 'Describes the archive age rather than its improved usability', 'Introduces money without support', 'Describes physical weakness, not usability'] }),
  b({ id: 'wic-02', skillId: 'words-in-context', domain: 'craft-structure', difficulty: 1, stimulus: 'Rather than dismissing the unexpected measurement, the physicist treated it as ____ and repeated the experiment under stricter controls.', prompt: 'Which choice completes the text with the most logical and precise word or phrase?', choices: ['instructive', 'ordinary', 'definitive', 'irrelevant'], answer: 0, explanation: 'Repeating the experiment shows that the physicist viewed the surprise as potentially informative, or instructive.', traps: ['Supported', 'Misses the importance of the surprise', 'Too strong before replication', 'Reverses the decision to investigate'] }),
  b({ id: 'wic-03', skillId: 'words-in-context', domain: 'craft-structure', difficulty: 2, stimulus: 'The architect did not reproduce the old station exactly. Instead, she ____ its arched roof in a lighter structure suited to the new library.', prompt: 'Which choice completes the text with the most logical and precise word or phrase?', choices: ['reinterpreted', 'concealed', 'measured', 'abandoned'], answer: 0, explanation: 'The new design preserves an idea from the station while changing its form, which means the architect reinterpreted it.', traps: ['Supported', 'Opposite of keeping the roof idea visible', 'A possible action but not the described design move', 'Contradicted by reuse of the arched roof'] }),
  b({ id: 'wic-04', skillId: 'words-in-context', domain: 'craft-structure', difficulty: 2, stimulus: 'Because the surviving diary contains entries from only three months, any account of the expedition based on it must remain ____ rather than complete.', prompt: 'Which choice completes the text with the most logical and precise word or phrase?', choices: ['partial', 'objective', 'celebrated', 'predictive'], answer: 0, explanation: 'The limited time span means the account can cover only part of the expedition.', traps: ['Supported', 'Completeness does not establish objectivity', 'Reputation is not discussed', 'The account concerns past events'] }),
  b({ id: 'wic-05', skillId: 'words-in-context', domain: 'craft-structure', difficulty: 3, stimulus: 'At first the two maps appear incompatible, but the discrepancy is ____ once differences in scale are taken into account: both depict the same shoreline.', prompt: 'Which choice completes the text with the most logical and precise word or phrase?', choices: ['resolved', 'magnified', 'predicted', 'preserved'], answer: 0, explanation: 'Accounting for scale removes the apparent conflict, so the discrepancy is resolved.', traps: ['Supported', 'Opposite direction', 'No earlier prediction is described', 'Contradicts removal of the conflict'] }),
  b({ id: 'wic-06', skillId: 'words-in-context', domain: 'craft-structure', difficulty: 4, stimulus: 'The critic called the novel restrained, not because it avoids emotion, but because its most painful scenes are ____ through plain description rather than announced through dramatic commentary.', prompt: 'Which choice completes the text with the most logical and precise word or phrase?', choices: ['conveyed', 'disputed', 'postponed', 'simplified'], answer: 0, explanation: 'The scenes communicate emotion through plain description, so conveyed fits both meaning and grammar.', traps: ['Supported', 'No disagreement is described', 'Timing is not at issue', 'Plain description does not mean the pain is made simpler'] }),

  b({ id: 'tsp-01', skillId: 'text-structure-purpose', domain: 'craft-structure', difficulty: 1, stimulus: 'Mangrove roots slow coastal water. This reduction in speed allows suspended sediment to settle, gradually building soil around the trees.', prompt: 'Which choice best describes the function of the second sentence in the text as a whole?', choices: ['It explains a consequence of the process named in the first sentence.', 'It disputes the observation in the first sentence.', 'It defines a term used in the first sentence.', 'It introduces an unrelated benefit of mangroves.'], answer: 0, explanation: 'The second sentence explains what happens because mangrove roots slow the water.', traps: ['Supported', 'The sentences agree', 'No term is defined', 'The consequence is directly related'] }),
  b({ id: 'tsp-02', skillId: 'text-structure-purpose', domain: 'craft-structure', difficulty: 2, stimulus: 'Early models assumed the moon was geologically inactive. Yet instruments placed on its surface recorded repeated tremors, some strong enough to shift loose material.', prompt: 'Which choice best states the function of the second sentence?', choices: ['It presents evidence that challenges an earlier assumption.', 'It gives an example that confirms the early models.', 'It explains why instruments could not measure tremors.', 'It changes the topic from geology to engineering.'], answer: 0, explanation: 'The recorded tremors conflict with the assumption that the moon was inactive.', traps: ['Supported', 'The evidence challenges rather than confirms', 'The instruments did record tremors', 'The topic remains lunar geology'] }),
  b({ id: 'tsp-03', skillId: 'text-structure-purpose', domain: 'craft-structure', difficulty: 3, stimulus: 'Some biologists describe urban foxes as unusually bold. In one study, however, foxes approached an unfamiliar plastic cylinder placed in a city park only when it had been scented with cooked meat; identical unscented cylinders were largely ignored.', prompt: 'Which choice best describes the overall structure of the text?', choices: ['It presents a common characterization, qualifies it with a study, and offers a narrower explanation.', 'It lists two unrelated explanations and rejects both.', 'It describes a method and argues that the method should be abandoned.', 'It states a finding, repeats it, and then gives a historical example.'], answer: 0, explanation: 'The passage moves from a broad view to qualifying evidence and a more limited account.', traps: ['Supported', 'The ideas are related and one is not fully rejected', 'No method is criticized', 'The final sentence interprets rather than gives history'] }),
  b({ id: 'tsp-04', skillId: 'text-structure-purpose', domain: 'craft-structure', difficulty: 4, stimulus: 'The museum label identifies the bowl as ceremonial. Its uneven wear, though, is concentrated along the rim and base, the same places that show wear on ordinary cooking vessels. These marks do not prove daily use, but they make an exclusively ceremonial role less certain.', prompt: 'What is the main purpose of the text?', choices: ['To use physical evidence to question a categorical interpretation', 'To prove that all ceremonial bowls were used for cooking', 'To explain how museum labels are physically attached to objects', 'To compare the artistic quality of ceremonial and ordinary bowls'], answer: 0, explanation: 'The wear pattern is used to make the exclusive ceremonial interpretation less certain, not to prove an alternative.', traps: ['Supported', 'Too broad and too certain', 'Confuses label content with label hardware', 'Artistic quality is not discussed'] }),
  b({ id: 'tsp-05', skillId: 'text-structure-purpose', domain: 'craft-structure', difficulty: 5, stimulus: 'A model can be valuable even when its assumptions are unrealistic. A frictionless surface, for example, exists nowhere in nature, but imagining one isolates the effect of friction and makes its role easier to study.', prompt: 'Which choice best states the function of the example in the text?', choices: ['It illustrates how an unrealistic assumption can clarify a real influence.', 'It demonstrates that friction has no effect in natural systems.', 'It identifies a case in which a model failed because it was too simple.', 'It argues that researchers should replace models with direct observation.'], answer: 0, explanation: 'The frictionless surface example shows that simplification can isolate and clarify one factor.', traps: ['Supported', 'Reverses the point', 'The model is presented as useful', 'The passage defends models'] }),

  b({ id: 'ctc-01', skillId: 'cross-text-connections', domain: 'craft-structure', difficulty: 2, stimulus: 'Text 1: Restoring city streams can lower nearby air temperatures because open water and vegetation absorb heat.', secondaryStimulus: 'Text 2: Temperature benefits from restored streams vary greatly. In narrow, shaded streets, airflow may matter more than the added water.', prompt: 'How would the author of Text 2 most likely respond to the claim in Text 1?', choices: ['By agreeing that restoration can cool an area while emphasizing that local conditions affect the size of the benefit', 'By denying that vegetation can absorb heat', 'By arguing that every restored stream produces the same temperature change', 'By claiming that airflow never influences city temperature'], answer: 0, explanation: 'Text 2 accepts that benefits can occur but qualifies their size based on local conditions.', traps: ['Supported', 'Not stated', 'Opposite of Text 2', 'Opposite of Text 2'] }),
  b({ id: 'ctc-02', skillId: 'cross-text-connections', domain: 'craft-structure', difficulty: 3, stimulus: 'Text 1: The small scratches on the tablet are most likely counting marks because they occur in repeated groups of five.', secondaryStimulus: 'Text 2: Repeated groups alone cannot establish numerical use; decorative borders on objects from the same site show similar grouping.', prompt: 'Based on the texts, the authors would most likely disagree about which question?', choices: ['Whether repeated grouping is sufficient evidence that the scratches record numbers', 'Whether the tablet contains scratches', 'Whether objects were found at the site', 'Whether groups of five can be counted'], answer: 0, explanation: 'Text 1 treats grouping as evidence of counting, while Text 2 says grouping alone is insufficient.', traps: ['Supported', 'Both accept this observation', 'Neither disputes the site context', 'This is not their interpretive disagreement'] }),
  b({ id: 'ctc-03', skillId: 'cross-text-connections', domain: 'craft-structure', difficulty: 4, stimulus: "Text 1: Translating a poem should preserve its rhyme whenever possible because sound is part of the poem's meaning.", secondaryStimulus: 'Text 2: A forced rhyme can distort syntax and emphasis. Preserving the pattern of attention in a poem may therefore matter more than matching its end sounds.', prompt: 'Which choice best describes the relationship between the texts?', choices: ['Text 2 accepts the importance of sound but argues that another feature may take priority.', 'Text 2 rejects the idea that poetic form affects meaning.', 'Text 1 and Text 2 agree that syntax should always be altered to preserve rhyme.', 'Text 1 discusses readers while Text 2 discusses only poets.'], answer: 0, explanation: 'Text 2 does not dismiss sound; it ranks the preservation of attention above rhyme when the two conflict.', traps: ['Supported', 'Too strong', 'Opposite of Text 2', 'Misstates the subjects'] }),
  b({ id: 'ctc-04', skillId: 'cross-text-connections', domain: 'craft-structure', difficulty: 5, stimulus: 'Text 1: A decline in night brightness in the satellite record indicates that the city energy-saving policy worked.', secondaryStimulus: 'Text 2: The satellite sensor was replaced during the study period. The newer sensor is less responsive to the wavelengths produced by common streetlights.', prompt: 'How does Text 2 bear on the conclusion in Text 1?', choices: ['It identifies a measurement change that could create the appearance of a policy effect.', 'It supplies a second measure confirming the policy effect.', 'It shows that streetlights became brighter after the policy.', 'It establishes that satellite sensors cannot measure any urban light.'], answer: 0, explanation: 'A less responsive sensor could record lower brightness even without a real decline, creating a rival explanation.', traps: ['Supported', 'Text 2 undermines rather than confirms', 'Not supported', 'Overgeneralizes'] }),

  b({ id: 'cid-01', skillId: 'central-ideas-details', domain: 'information-ideas', difficulty: 1, stimulus: 'Octopuses can alter both the color and texture of their skin. These changes help them blend into rocky seafloors, but researchers have also observed rapid patterns during interactions with other octopuses. The patterns may therefore serve communication as well as camouflage.', prompt: 'Which choice best states the main idea of the text?', choices: ['Octopus skin changes may serve more than one function.', 'Octopuses change color only when hiding from predators.', 'Rocky seafloors prevent octopuses from communicating.', 'Researchers understand every octopus skin pattern.'], answer: 0, explanation: 'The passage presents camouflage and communication as two possible functions.', traps: ['Supported', 'Contradicted by social patterns', 'Not stated', 'Too certain'] }),
  b({ id: 'cid-02', skillId: 'central-ideas-details', domain: 'information-ideas', difficulty: 2, stimulus: 'Engineer Laila Mensah tested bricks made with different amounts of rice husk ash. Bricks containing 8 percent ash resisted compression better than conventional bricks, but bricks containing 20 percent ash were weaker. Mensah concluded that the additive can help only within a suitable range.', prompt: 'According to the text, what did Mensah conclude?', choices: ['The effect of rice husk ash depends on the amount used.', 'Any amount of ash strengthens bricks.', 'Conventional bricks contain 20 percent ash.', 'Compression resistance cannot be measured.'], answer: 0, explanation: 'The 8 percent and 20 percent results differ, supporting an amount-dependent effect.', traps: ['Supported', 'Contradicted by the 20 percent result', 'Not stated', 'Contradicted by the testing'] }),
  b({ id: 'cid-03', skillId: 'central-ideas-details', domain: 'information-ideas', difficulty: 3, stimulus: 'In many recordings, a whale call seems to end abruptly. Acoustic ecologist Mara Velez found that the apparent ending often reflects the lower limit of shipboard microphones: the call continues at frequencies the devices do not capture. Reanalysis with broader-range sensors revealed longer call sequences.', prompt: 'Which choice best states the main idea of the text?', choices: ['A limitation of recording equipment caused researchers to underestimate the length of some whale calls.', 'Whales shorten their calls when ships approach.', 'Broader-range sensors produce quieter recordings than shipboard microphones.', 'Most whale calls occur at frequencies no sensor can capture.'], answer: 0, explanation: 'The passage links apparent call endings to microphone range and shows that broader sensors reveal longer calls.', traps: ['Supported', 'No behavioral change is described', 'Volume is not discussed', 'Overstates the limitation'] }),
  b({ id: 'cid-04', skillId: 'central-ideas-details', domain: 'information-ideas', difficulty: 4, stimulus: 'A survey of old field notebooks found many precise observations that never appeared in published articles. Some entries concerned ordinary weather or common species and seemed unimportant at the time. Decades later, those routine records provide rare baselines for measuring environmental change.', prompt: 'Which choice best states the main idea of the text?', choices: ['Observations once considered routine can become valuable evidence when conditions change over time.', 'Published articles always contain less accurate data than field notebooks.', 'Historical researchers recorded weather only when it was unusual.', 'Environmental change makes recent observations unnecessary.'], answer: 0, explanation: 'The passage emphasizes how ordinary unpublished records gained value as historical baselines.', traps: ['Supported', 'Unsupported absolute comparison', 'Contradicted by ordinary records', 'Reverses the value of new observations'] }),

  b({ id: 'cet-01', skillId: 'command-evidence-textual', domain: 'information-ideas', difficulty: 2, stimulus: 'Nesting boxes installed in public parks are usually built from smooth planed timber, which is cheap to mill and easy to scrub out between seasons. Ornithologist Priya Raghunathan noticed that small songbirds using these boxes hesitated at the opening during rain, and that several lost their footing on the wet lip before getting inside. Over two breeding seasons she fitted a subset of boxes with a shallow grooved strip along the entrance and left the remaining boxes unchanged. Because heavy rain also alters how birds approach a box, she compared entries only across days with similar wind. Raghunathan claims that adding rough surfaces to nesting boxes helps small birds grip the entrance in wet weather.', prompt: "Which finding, if true, would most directly support the researcher's claim?", choices: ['In matched wet conditions, birds slipped less often at roughened entrances than at smooth entrances.', 'Birds used nesting boxes in both wet and dry regions.', 'Rough wood was more expensive than smooth plastic.', 'Some birds approached the boxes from nearby branches.'], answer: 0, explanation: 'The matched comparison directly connects surface roughness to grip performance in wet weather.', traps: ['Supported', 'Related setting but no roughness comparison', 'Cost does not test grip', 'Approach behavior does not test grip'] }),
  b({ id: 'cet-02', skillId: 'command-evidence-textual', domain: 'information-ideas', difficulty: 3, stimulus: "The Havenport Courier began in 1851 as a four-page weekly serving dockworkers and merchants, and its earliest circulation ledgers list only subscribers living within walking distance of the harbor. Those ledgers break off in 1869, which has made the paper's later reach difficult to establish from the newspaper's own records. Historian Amara Oyelaran has instead assembled indirect sources from the following two decades, among them freight manifests, a printer's invoices for paper stock, and family correspondence held in the surrounding countryside. On the basis of this material she argues that the Courier reached readers well beyond the city itself by the 1880s.", prompt: "Which finding would most directly support the historian's argument?", choices: ['Letters from rural subscribers mention receiving the newspaper by rail in 1884.', 'The newspaper office moved to a larger city building in 1881.', 'Port workers frequently purchased newspapers near the docks.', 'The city population increased during the 1880s.'], answer: 0, explanation: 'Rural subscribers receiving the paper are direct evidence of readership beyond the city.', traps: ['Supported', 'Office size does not establish geographic reach', 'These readers are still in the city', 'Population growth does not establish distribution'] }),
  b({ id: 'cet-03', skillId: 'command-evidence-textual', domain: 'information-ideas', difficulty: 4, stimulus: "Many flowering plants carry pigment patterns that are invisible to people but conspicuous to bees, whose vision extends into the ultraviolet. These markings frequently radiate outward from the center of the bloom, where nectar is stored, and they are strongest in species that depend on a small number of pollinator visits. The long-standing explanation is that such patterns raise a flower's contrast against surrounding foliage, making the bloom easier for a foraging bee to pick out from a distance. A group of biologists has proposed a narrower function: that a flower's bright ultraviolet markings guide bees toward nectar once the bee has landed, rather than merely making the flower easier to notice.", prompt: 'Which result would most directly support the proposal?', choices: ['Bees found nectar faster on flowers with intact markings than on equally visible flowers whose markings were covered.', 'Bees visited ultraviolet flowers more often than flowers kept in darkness.', 'Flowers with markings produced the same amount of nectar as flowers without them.', 'The markings were visible under laboratory lamps.'], answer: 0, explanation: 'Equal visibility isolates the guiding pattern and the faster nectar location measures the proposed function.', traps: ['Supported', 'Confounds markings with visibility', 'Nectar amount does not test guidance', 'Visibility alone does not test guidance'] }),
  b({ id: 'cet-04', skillId: 'command-evidence-textual', domain: 'information-ideas', difficulty: 5, stimulus: 'When a regional transit authority cut the standard bus fare by half, ridership on the affected routes rose within three months and has remained elevated since. The reduction was introduced to pull cars off congested downtown streets, and early coverage treated the ridership figures as evidence that it had done so. Economist Devesh Kulkarni cautions that a rise in boardings says nothing on its own about where the additional riders came from, because the lower fare was available to everyone regardless of how they had traveled before. Drawing on surveys collected at boarding, he claims that the fare reduction increased bus use primarily among people who had previously walked, not among people who had driven.', prompt: 'Which finding, if true, would most directly weaken the claim?', choices: ['Most new bus riders reported that before the fare change they usually drove the same route.', 'Total bus ridership rose after the fare reduction.', 'Some regular bus riders continued to buy monthly passes.', 'Walking remained common on routes without bus service.'], answer: 0, explanation: 'If most new riders previously drove, the claimed source of the increase is reversed.', traps: ['Supported weakening evidence', 'Supports increase but not its source', 'Existing riders are irrelevant to the source of new riders', 'Routes without service do not identify new bus riders'] }),

  b({ id: 'ceq-01', skillId: 'command-evidence-quantitative', domain: 'information-ideas', difficulty: 2, stimulus: 'Ninety seedlings of a single native shrub were assigned at random to three light conditions in a research nursery: full sun, partial shade produced by a mesh canopy, and full shade beneath a solid cover. Every group received the same soil mixture, the same volume of water on the same schedule, and containers of identical size, so that light was the only planned difference among them. After six weeks the researchers counted the seedlings still alive in each condition and expressed the result as a percentage of the ninety originally planted. A student reviewing the results claims that the shaded treatment produced the highest average seedling survival.', table: { caption: 'Average seedling survival after six weeks', headers: ['Treatment', 'Survival'], rows: [['Full sun', '58%'], ['Partial shade', '76%'], ['Full shade', '63%']] }, prompt: 'Which choice most effectively uses data from the table to support the claim?', choices: ['Survival in partial shade was 76%, higher than in full sun or full shade.', 'Full shade survival was 5 percentage points above full sun.', 'All treatments had survival above 50%.', 'Partial shade and full shade differed by 13%.'], answer: 0, explanation: 'The claim is about the highest survival, and the first choice compares partial shade with both alternatives.', traps: ['Supported', 'True but does not show which is highest', 'True but too general', 'Uses percent rather than percentage points and does not compare all groups'] }),
  b({ id: 'ceq-02', skillId: 'command-evidence-quantitative', domain: 'information-ideas', difficulty: 4, stimulus: 'The Halversen Museum closed for eighteen months of structural renovation and reopened all of its galleries on the same day, resuming its former schedule of daytime and evening programs. Because daytime programs had drawn considerably larger audiences before the closure, raw attendance counts would not show which format was recovering faster. Staff therefore expressed each monthly count as a percentage of attendance at the corresponding program type before the renovation, and tracked both series for six months after reopening. Admission prices, the number of sessions offered in each format, and the advertising budget for each series were held at their pre-closure levels throughout, so that the comparison would not be confounded by a change the museum itself had made. The resulting figures appear in the table. A curator argues that attendance recovered more quickly for evening programs than for daytime programs after renovations.', table: { caption: 'Program attendance as a percentage of pre-renovation attendance', headers: ['Month after reopening', 'Daytime', 'Evening'], rows: [['1', '61%', '64%'], ['3', '70%', '82%'], ['6', '86%', '96%']] }, prompt: "Which choice most effectively uses data from the table to support the curator's argument?", choices: ['From month 1 to month 6, evening attendance rose 32 percentage points, compared with 25 for daytime attendance.', 'At month 1, both program types were below 65%.', 'At month 6, neither program type exceeded its pre-renovation attendance.', 'Daytime attendance rose in every measured month.'], answer: 0, explanation: 'The larger increase directly supports faster recovery for evening programs.', traps: ['Supported', 'Does not compare recovery speed', 'True but does not compare speed', 'Only one series is described'] }),

  b({ id: 'inf-01', skillId: 'inferences', domain: 'information-ideas', difficulty: 1, stimulus: 'A desert plant opens its pores mainly at night, when air temperatures fall and humidity rises. Opening them during the day would permit immediate photosynthesis but would also expose moist internal tissue to intense heat and dry wind. Because less water evaporates after dark, the plant can absorb carbon dioxide while releasing much less moisture than it otherwise would.', prompt: 'Which choice most logically completes the text?', choices: ['helps the plant conserve water while it still acquires carbon dioxide', 'prevents the plant from taking in carbon dioxide at any point in the day', 'depends on nighttime temperatures being higher than daytime temperatures', 'requires substantial water loss before the pores are able to open'], answer: 0, explanation: 'Night opening is explicitly linked to reduced evaporation, so the timing conserves water while carbon dioxide is still taken in.', traps: ['Supported', 'Contradicted by the description of nighttime uptake', 'Contradicted by the statement that temperatures fall at night', 'Reverses the relationship between water loss and pore opening'] }),
  b({ id: 'inf-02', skillId: 'inferences', domain: 'information-ideas', difficulty: 2, stimulus: 'For years the returns box at the Ferndale Public Library stood behind the building, at the end of a service lane that patrons could reach only on foot. After the box was moved to the main entrance, the number of books returned past their due date fell noticeably.', prompt: 'Which choice most logically completes the text?', choices: ['making the returns box easier to reach encouraged more timely returns', 'the library had quietly shortened every loan period during the same year', 'patrons borrowed fewer books once the box was moved to the entrance', 'all of the books previously recorded as overdue had in fact been lost'], answer: 0, explanation: 'The only documented change was the location of the box, so easier access is the best-supported account of the decline in late returns.', traps: ['Supported', 'Contradicted by the statement that no lending rule changed', 'No borrowing counts are reported', 'Too absolute and unsupported'] }),
  b({ id: 'inf-03', skillId: 'inferences', domain: 'information-ideas', difficulty: 3, stimulus: 'A species of moth in temperate woodland normally emerges from its pupal case in late spring. Entomologist Kenji Watanabe reared several hundred pupae in chambers that differed only in temperature, holding humidity, light, food, and density constant across every group. In the warmer chambers individuals emerged several days earlier than in the cooler ones, but the total number that successfully emerged did not differ.', prompt: 'Which choice most logically completes the text?', choices: ['influences when the moths emerge without changing how many of them do', 'prevents most individuals from emerging once conditions become warmer', 'is itself determined by the timing at which the moths emerge', 'affects every moth species in exactly the way it affects this one'], answer: 0, explanation: 'Emergence shifted earlier while the total number emerging stayed the same, so temperature affected timing rather than success.', traps: ['Supported', 'Contradicted by the unchanged total', 'Reverses cause and effect', 'Overgeneralizes beyond the single species studied'] }),
  b({ id: 'inf-04', skillId: 'inferences', domain: 'information-ideas', difficulty: 5, stimulus: 'In a study of musical memory, listeners first learned a set of short melodies played on a familiar acoustic instrument. When those melodies were played again at a noticeably faster or slower tempo, listeners still identified them accurately. Recognition fell sharply, however, when the same melodies were rendered with an unfamiliar synthesized timbre, even though the tempo was held constant.', prompt: 'Which choice most logically completes the text?', choices: ['depended more on the familiarity of a melody timbre than on a moderate change in tempo', 'required that both the instrument and the tempo remain exactly as they were in training', 'been entirely unaffected by tempo under any circumstances', 'reflected the greater loudness of familiar instruments compared with synthesized sounds'], answer: 0, explanation: 'Recognition survived a tempo change with a familiar timbre but fell with an unfamiliar timbre at constant tempo, pointing to timbre as the stronger influence.', traps: ['Supported', 'Contradicted by accurate recognition at a new tempo', 'Too absolute', 'Loudness was matched across the conditions'] }),

  b({ id: 'bnd-01', skillId: 'boundaries', domain: 'standard-english', difficulty: 1, stimulus: 'Ice cover on the lake is not uniform from shore to shore. The lake freezes each winter ____ the moving water near its outlet usually remains open.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: ['but', 'but,', ', but', '; but'], answer: 2, explanation: 'Two independent clauses joined by but require a comma before the coordinating conjunction.', traps: ['Missing comma between independent clauses', 'Comma placed after conjunction', 'Supported', 'Semicolon before a coordinating conjunction is not needed'] }),
  b({ id: 'bnd-02', skillId: 'boundaries', domain: 'standard-english', difficulty: 1, stimulus: 'Students are asked to bring their own supplies to the first session. The workshop requires three tools ____ a ruler, a craft knife, and a cutting mat.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: [',', ':', ';', ''], answer: 1, explanation: 'A colon follows a complete clause and introduces the list of tools.', traps: ['Comma does not properly introduce this list after a complete clause', 'Supported', 'A semicolon does not introduce a list', 'A boundary is needed'] }),
  b({ id: 'bnd-03', skillId: 'boundaries', domain: 'standard-english', difficulty: 2, stimulus: 'The calibration run was intended to confirm that the equipment was working. The first trial produced no visible change ____ the team adjusted the sensor and repeated the procedure.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: [', therefore', '; therefore,', ' therefore,', ': therefore'], answer: 1, explanation: 'A semicolon joins the independent clauses, and the transition therefore is followed by a comma.', traps: ['Comma splice', 'Supported', 'Missing boundary', 'Colon does not express this result relationship correctly'] }),
  b({ id: 'bnd-04', skillId: 'boundaries', domain: 'standard-english', difficulty: 2, stimulus: 'Reviewers at the time speculated at length about who had written it. The novel, which was published anonymously ____ became an immediate success.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: [',', ';', ':', ''], answer: 0, explanation: 'The nonessential which clause begins after a comma and must also close with a comma.', traps: ['Supported', 'Semicolon cannot separate the subject from its verb', 'Colon cannot separate the subject from its verb', 'Leaves the nonessential clause unclosed'] }),
  b({ id: 'bnd-05', skillId: 'boundaries', domain: 'standard-english', difficulty: 3, stimulus: 'The marsh sits roughly midway along the route the flock follows each autumn. During migration, the birds stop at the marsh to rest ____ feeding there only when insects are abundant.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: [',', ';', ':', ''], answer: 0, explanation: 'The participial phrase feeding there modifies the birds and is properly set off with a comma.', traps: ['Supported', 'The second part is not an independent clause', 'The second part does not explain a complete clause in the required way', 'The modifying phrase needs separation'] }),
  b({ id: 'bnd-06', skillId: 'boundaries', domain: 'standard-english', difficulty: 4, stimulus: 'Field notes from the survey record when each observation was made. What surprised the excavators was not the coin age ____ it was the distance between the coin and the nearest known settlement.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: [', however,', '; rather,', ', rather', ': rather,'], answer: 1, explanation: 'The two independent clauses contrast alternatives. A semicolon creates the boundary, and rather is followed by a comma.', traps: ['Comma splice with an interrupting transition', 'Supported', 'Comma splice', 'A colon is not the best boundary for two contrasted clauses with rather'] }),
  b({ id: 'bnd-07', skillId: 'boundaries', domain: 'standard-english', difficulty: 5, stimulus: 'The committee adopted the proposal for one reason ____ it preserved the wetland without delaying construction.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: [', namely,', '; namely,', ':', ''], answer: 2, explanation: 'The complete first clause announces one reason, and the second clause states that reason. A colon is appropriate.', traps: ['Comma splice', 'A semicolon suggests two parallel statements rather than an announced explanation', 'Supported', 'A boundary is needed'] }),

  b({ id: 'fss-01', skillId: 'form-structure-sense', domain: 'standard-english', difficulty: 1, stimulus: 'A collection of glass negatives from the expedition ____ in the university archive.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: ['is stored', 'are stored', 'store', 'have stored'], answer: 0, explanation: 'The subject collection is singular, so it takes the singular verb is stored.', traps: ['Supported', 'Agrees with nearby negatives instead of subject collection', 'Wrong voice and agreement', 'Wrong agreement and form'] }),
  b({ id: 'fss-02', skillId: 'form-structure-sense', domain: 'standard-english', difficulty: 1, stimulus: 'By the time the lecture began, the technicians ____ the audio system twice.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: ['had tested', 'test', 'will test', 'are testing'], answer: 0, explanation: 'The testing was completed before another past event, so past perfect had tested is logical.', traps: ['Supported', 'Wrong tense', 'Wrong time direction', 'Wrong tense'] }),
  b({ id: 'fss-03', skillId: 'form-structure-sense', domain: 'standard-english', difficulty: 2, stimulus: 'Using a new imaging method, ____ revealed faint writing beneath the painted surface.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: ['the conservators', 'faint writing', 'the painted surface', 'the discovery'], answer: 0, explanation: 'The opening modifier must describe the people using the method, so conservators must follow it.', traps: ['Supported', 'Creates a dangling modifier', 'Creates a dangling modifier', 'Creates a dangling modifier'] }),
  b({ id: 'fss-04', skillId: 'form-structure-sense', domain: 'standard-english', difficulty: 2, stimulus: 'The two teams shared ____ results before publishing the joint report.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: ['their', 'there', "they're", 'its'], answer: 0, explanation: 'Their is the plural possessive determiner referring to the two teams.', traps: ['Supported', 'Location word', 'Contraction for they are', 'Singular possessive'] }),
  b({ id: 'fss-05', skillId: 'form-structure-sense', domain: 'standard-english', difficulty: 3, stimulus: 'Neither the original sketch nor the later copies ____ the missing inscription clearly.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: ['shows', 'show', 'showing', 'has showed'], answer: 1, explanation: 'With neither nor, the verb agrees with the nearer subject copies, which is plural.', traps: ['Agrees with the more distant singular subject', 'Supported', 'Incomplete verb', 'Wrong agreement and nonstandard participle'] }),
  b({ id: 'fss-06', skillId: 'form-structure-sense', domain: 'standard-english', difficulty: 4, stimulus: 'The lab will compare the new coating with ____ used in the earlier trial.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: ['the one', 'that', 'those', 'them'], answer: 0, explanation: 'The one clearly and logically substitutes for the singular noun coating.', traps: ['Supported', 'That creates an awkward or incomplete comparison here', 'Plural substitute for a singular noun', 'Object pronoun lacks a clear grammatical structure'] }),
  b({ id: 'fss-07', skillId: 'form-structure-sense', domain: 'standard-english', difficulty: 5, stimulus: 'The poet was one of several writers who ____ the journal during its first year.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: ['edited', 'edits', 'has edited', 'was editing'], answer: 0, explanation: 'Who refers to the plural writers, and the completed action during the first year calls for simple past edited.', traps: ['Supported', 'Wrong agreement and tense', 'Wrong agreement and time relationship', 'Singular progressive does not fit the plural antecedent or completed period'] }),

  b({ id: 'rhs-01', skillId: 'rhetorical-synthesis', domain: 'expression-ideas', difficulty: 1, stimulus: 'While researching a topic, a student has taken the following notes.\n• The Lumen Tower opened in 1932 as a commercial office building.\n• Its upper floors housed law firms and shipping agents for five decades.\n• The city purchased the building in 1985.\n• It reopened as a public library in 1988.\nThe student wants to emphasize a change in how the building is used.', prompt: 'Which choice most effectively uses relevant information from the notes to accomplish this goal?', choices: ['Originally an office building, the Lumen Tower became a public library in 1988.', 'The Lumen Tower opened in 1932 and is a tall building.', 'Public libraries serve many kinds of readers.', 'The Lumen Tower was an office building that opened.'], answer: 0, explanation: 'The choice directly contrasts the original and later uses and includes the date of change.', traps: ['Supported', 'Does not state the changed use', 'Not from the notes', 'States only the original use'] }),
  b({ id: 'rhs-02', skillId: 'rhetorical-synthesis', domain: 'expression-ideas', difficulty: 2, stimulus: 'While researching a topic, a student has taken the following notes.\n• Botanist Imani Okafor studies rice varieties that tolerate salty soil.\n• Rising seawater has made many coastal paddies difficult to farm.\n• Her team tested 24 varieties in identical field plots.\n• Variety R7 produced the most grain in salty soil.\nThe student wants to introduce the research and its key finding to an audience already familiar with rice farming.', prompt: 'Which choice most effectively uses relevant information from the notes?', choices: ["In a test of 24 salt-tolerant rice varieties, Imani Okafor's team found that R7 produced the most grain in salty soil.", 'Imani Okafor is a botanist, and rice is an important crop.', 'Twenty-four varieties of rice have short names, including R7.', 'Salty soil contains more salt than ordinary soil.'], answer: 0, explanation: 'The sentence names the researcher, research focus, test, and central finding.', traps: ['Supported', 'Adds a general fact and omits the finding', 'Misuses the notes and misses the goal', 'General statement does not introduce the research'] }),
  b({ id: 'rhs-03', skillId: 'rhetorical-synthesis', domain: 'expression-ideas', difficulty: 3, stimulus: 'While researching a topic, a student has taken the following notes.\n• Biologist Nia Patel recorded frog calls at Pond A and Pond B.\n• Pond A lies beside a six-lane highway.\n• Pond B lies within a quiet nature reserve.\n• Calls at Pond A averaged 0.8 kHz higher in pitch.\nThe student wants to compare the findings at the two ponds.', prompt: 'Which choice most effectively uses relevant information from the notes?', choices: ['Frog calls at highway-adjacent Pond A averaged 0.8 kHz higher than those at quiet Pond B.', 'Nia Patel recorded frogs at two ponds, one of which was Pond A.', 'Pond B is located in a quiet reserve away from Pond A.', 'Highways can be loud, and frogs make calls.'], answer: 0, explanation: 'The sentence directly compares the measured call frequencies and supplies the relevant setting.', traps: ['Supported', 'Does not compare findings', 'Compares locations but not findings', 'General facts do not report the finding'] }),
  b({ id: 'rhs-04', skillId: 'rhetorical-synthesis', domain: 'expression-ideas', difficulty: 4, stimulus: 'While researching a topic, a student has taken the following notes.\n• The Koru ferry was rebuilt with an aluminum hull in place of steel.\n• The change reduced the mass of the vessel by 18 percent.\n• The lighter ferry burned less fuel on the same route.\n• Passenger capacity did not change.\nThe student wants to explain why the hull material improved efficiency.', prompt: 'Which choice most effectively uses relevant information from the notes?', choices: ["By reducing the ferry's mass 18 percent without changing capacity, the aluminum hull lowered fuel use on the same route.", 'The Koru ferry has an aluminum hull and carries passengers.', 'Aluminum is a material used in many vehicles and buildings.', 'Passenger capacity did not change, although the route remained the same.'], answer: 0, explanation: 'The choice connects material to lower mass and then to lower fuel use while noting capacity was preserved.', traps: ['Supported', 'Lists facts without the efficiency mechanism', 'Not from the notes and misses the specific result', 'Omits the hull and fuel mechanism'] }),
  b({ id: 'rhs-05', skillId: 'rhetorical-synthesis', domain: 'expression-ideas', difficulty: 5, stimulus: 'While researching a topic, a student has taken the following notes.\n• Critics long dated a civic mural to 1910 from its signature.\n• Chemist Aya Ruiz analyzed the blue pigment in the sky.\n• That pigment was not sold commercially until 1924.\n• Ruiz does not claim to know the exact year of painting.\nThe student wants to show how the analysis challenges the traditional date without overstating the evidence.', prompt: 'Which choice most effectively uses relevant information from the notes?', choices: ["Because the mural contains a pigment unavailable until 1924, Ruiz's analysis rules out the traditional 1910 date but does not establish an exact later year.", 'Ruiz proved that the mural was painted in 1924.', 'The mural signature says 1910, so its date cannot be questioned.', 'Blue pigment became commercially available sometime after critics began studying murals.'], answer: 0, explanation: 'The sentence rules out 1910 while preserving the stated limit that the exact year remains unknown.', traps: ['Supported', 'Overstates the evidence', 'Ignores the chemical evidence', 'Too vague and misses the conclusion'] }),

  b({ id: 'trn-01', skillId: 'transitions', domain: 'expression-ideas', difficulty: 1, stimulus: 'A greenhouse trial compared how container color affects early growth in bean seedlings. The first seedlings received six hours of light. ____, the second group received the same amount.', prompt: 'Which choice most logically completes the text?', choices: ['Likewise', 'However', 'Therefore', 'For example'], answer: 0, explanation: 'The two groups received similar treatment, so Likewise states the relationship.', traps: ['Supported', 'No contrast', 'The second treatment is not a result', 'The second group is parallel, not an example of a general claim'] }),
  b({ id: 'trn-02', skillId: 'transitions', domain: 'expression-ideas', difficulty: 1, stimulus: 'A week without rain had led hikers to expect firm ground throughout the reserve. The path looked dry near the entrance. ____, several sections beyond the first bend were flooded.', prompt: 'Which choice most logically completes the text?', choices: ['However', 'Similarly', 'Therefore', 'For instance'], answer: 0, explanation: 'The flooded later sections contrast with the dry entrance.', traps: ['Supported', 'The conditions differ', 'Flooding is not caused by the appearance at the entrance', 'The second sentence contrasts rather than exemplifies'] }),
  b({ id: 'trn-03', skillId: 'transitions', domain: 'expression-ideas', difficulty: 2, stimulus: 'A design team evaluating materials for a new turbine ranked the candidates by heat tolerance. The alloy remained stable at high temperatures. ____, engineers selected it for the engine casing.', prompt: 'Which choice most logically completes the text?', choices: ['Consequently', 'Nevertheless', 'Meanwhile', 'Specifically'], answer: 0, explanation: 'Selection for the casing is a result of the alloy stability.', traps: ['Supported', 'No concession', 'The relationship is causal, not merely simultaneous', 'The second sentence is a result, not a narrower restatement'] }),
  b({ id: 'trn-04', skillId: 'transitions', domain: 'expression-ideas', difficulty: 3, stimulus: 'Camouflage in insects can involve pigment, outline, or both at once. Many insects use color for camouflage. ____, the walking leaf insect resembles both the shape and green tone of a leaf.', prompt: 'Which choice most logically completes the text?', choices: ['For example', 'Instead', 'As a result', 'Nevertheless'], answer: 0, explanation: 'The walking leaf insect is a specific example of the general statement.', traps: ['Supported', 'It does not replace the first idea', 'The insect is not caused by the sentence itself', 'No surprising contrast'] }),
  b({ id: 'trn-05', skillId: 'transitions', domain: 'expression-ideas', difficulty: 4, stimulus: 'A recent translation of a nineteenth-century novel has divided reviewers. The new translation preserves the original sentence order. ____, it changes several metaphors to sound natural in the target language.', prompt: 'Which choice most logically completes the text?', choices: ['At the same time', 'For that reason', 'In other words', 'Afterward'], answer: 0, explanation: 'The translation preserves one feature while simultaneously changing another, so At the same time fits.', traps: ['Supported', 'The metaphor changes are not caused by sentence-order preservation', 'The second sentence is not a restatement', 'No sequence is described'] }),
  b({ id: 'trn-06', skillId: 'transitions', domain: 'expression-ideas', difficulty: 5, stimulus: 'Astronomers hope one day to detect plant life on planets orbiting other stars. The telescope cannot resolve individual trees on the distant planet. ____, shifts in reflected light may reveal broad seasonal changes in its vegetation.', prompt: 'Which choice most logically completes the text?', choices: ['Even so', 'In addition', 'For example', 'Accordingly'], answer: 0, explanation: 'The second sentence identifies what may still be possible despite the limitation, so Even so expresses concession.', traps: ['Supported', 'Misses the limitation-to-possibility contrast', 'The second sentence is not merely an example', 'It is not a direct result of the inability'] }),
]

const extraBlueprints: Blueprint[] = [
  b({ id: 'wic-07', skillId: 'words-in-context', domain: 'craft-structure', difficulty: 2, stimulus: 'The software was designed to ____ the cataloging process: tasks that once took an hour could now be completed in minutes.', prompt: 'Which choice completes the text with the most logical and precise word or phrase?', choices: ['expedite', 'document', 'observe', 'complicate'], answer: 0, explanation: 'The reduced completion time shows that the software speeds up, or expedites, the process.', traps: ['Supported', 'Recording is not the stated effect', 'Watching is not the stated effect', 'Opposite of the faster process'] }),
  b({ id: 'wic-08', skillId: 'words-in-context', domain: 'craft-structure', difficulty: 3, stimulus: 'Although the two fossils look nearly identical, a small difference in tooth structure is ____: it indicates that the animals ate different foods.', prompt: 'Which choice completes the text with the most logical and precise word or phrase?', choices: ['consequential', 'decorative', 'accidental', 'temporary'], answer: 0, explanation: 'The difference has an important implication for diet, so consequential is precise.', traps: ['Supported', 'The tooth is functional, not ornamental', 'The text treats the difference as meaningful', 'Fossil anatomy is not temporary'] }),
  b({ id: 'wic-09', skillId: 'words-in-context', domain: 'craft-structure', difficulty: 5, stimulus: 'The essay does not reject the standard account; it ____ it by showing that local merchants, not only national officials, shaped the policy.', prompt: 'Which choice completes the text with the most logical and precise word or phrase?', choices: ['complicates', 'recites', 'conceals', 'invalidates'], answer: 0, explanation: 'Adding another important cause makes the standard account more complex without rejecting it.', traps: ['Supported', 'Repeating is not adding a causal factor', 'The essay reveals rather than hides', 'Too strong because the account is not rejected'] }),
  b({ id: 'wic-10', skillId: 'words-in-context', domain: 'craft-structure', difficulty: 5, stimulus: 'Archaeologists found charred seeds beside a hearth and initially treated them as evidence that the settlement residents cultivated the plant. Wild plants of the same species grew nearby, however, and the seeds show no traits associated with domestication. The cultivation claim is therefore best regarded as ____ pending additional evidence.', prompt: 'Which choice completes the text with the most logical and precise word or phrase?', choices: ['conclusive', 'incidental', 'provisional', 'incoherent'], answer: 2, explanation: 'The evidence permits the cultivation claim but does not establish it, so the claim remains provisional.', traps: ['Too certain given the rival wild source', 'Describes the seeds as unimportant rather than the claim as uncertain', 'Supported', 'The claim is intelligible even though it is not established'] }),
  b({ id: 'wic-11', skillId: 'words-in-context', domain: 'craft-structure', difficulty: 4, stimulus: 'The composer often revised passages after hearing them performed, but the alterations were rarely wholesale. A shifted accent or shortened rest could subtly redirect a phrase while leaving its melodic outline intact. Her revisions were thus typically ____ rather than transformative.', prompt: 'Which choice completes the text with the most logical and precise word or phrase?', choices: ['incremental', 'arbitrary', 'theoretical', 'ornamental'], answer: 0, explanation: 'The examples describe small, cumulative changes that preserve the main outline, making incremental precise.', traps: ['Supported', 'The revisions respond to performance rather than chance', 'The changes are made in actual passages', 'The changes affect phrasing, not merely decoration'] }),
  b({ id: 'tsp-06', skillId: 'text-structure-purpose', domain: 'craft-structure', difficulty: 2, stimulus: "The glass frog's underside is translucent. As a result, much of the blood pooled in its liver while it sleeps is hidden from view, increasing the frog's transparency.", prompt: 'Which choice best describes the function of the second sentence?', choices: ['It explains a mechanism that increases the trait introduced in the first sentence.', 'It gives a reason the frog cannot sleep.', 'It contrasts the frog with an unrelated animal.', 'It defines what blood is.'], answer: 0, explanation: 'The second sentence explains how hiding blood contributes to translucence.', traps: ['Supported', 'No sleep problem is described', 'No other animal appears', 'No definition is given'] }),
  b({ id: 'tsp-07', skillId: 'text-structure-purpose', domain: 'craft-structure', difficulty: 4, stimulus: 'Researchers expected the oldest trees to host the most lichen species. The survey found the strongest predictor was bark texture, not age. Older trees often hosted more species only because their bark was usually rougher.', prompt: 'Which choice best states the main purpose of the text?', choices: ['To replace a simple age-based explanation with one based on a correlated feature', 'To show that lichen never grows on young trees', 'To argue that tree age and bark texture are identical', 'To describe how researchers measure tree height'], answer: 0, explanation: 'The study shifts the explanation from age itself to bark texture, which is correlated with age.', traps: ['Supported', 'Too absolute', 'Related but not identical', 'Height is not discussed'] }),
  b({ id: 'tsp-08', skillId: 'text-structure-purpose', domain: 'craft-structure', difficulty: 5, stimulus: 'A census of reef fish recorded fewer species in cloudy water than in clear water. The investigators first interpreted the difference as a biological response to low light. They later noted that the visual survey method also becomes less likely to detect small or camouflaged fish as visibility declines. The census may therefore understate cloudy-water diversity.', prompt: 'Which choice best describes the function of the third sentence in the text as a whole?', choices: ['It identifies a measurement limitation that offers an alternative explanation for the initial result.', 'It supplies evidence that low light reduces the number of fish species present.', 'It explains why small fish prefer clear water to cloudy water.', 'It establishes that visual surveys detect every fish in clear water.'], answer: 0, explanation: 'The third sentence introduces detection bias, which can account for the apparent species difference without a biological decline.', traps: ['Supported', 'It weakens rather than supports the biological interpretation', 'Preference is not measured', 'The survey is not claimed to be perfect in any condition'] }),
  b({ id: 'ctc-05', skillId: 'cross-text-connections', domain: 'craft-structure', difficulty: 3, stimulus: 'Text 1: Remote work reduced commuting time for many employees, leaving more time for exercise.', secondaryStimulus: 'Text 2: Time diaries show that saved commuting time was divided among exercise, sleep, household work, and paid work, with large differences among employees.', prompt: 'How would the author of Text 2 most likely respond to Text 1?', choices: ['The effect is plausible for some employees but does not describe how everyone used the saved time.', 'Saved commuting time was never used for exercise.', 'Every employee used the time in the same way.', 'Remote work increased commuting time.'], answer: 0, explanation: 'Text 2 allows exercise as one use but emphasizes varied allocation across employees.', traps: ['Supported', 'Contradicted by Text 2', 'Opposite of Text 2', 'Not supported'] }),
  b({ id: 'ctc-06', skillId: 'cross-text-connections', domain: 'craft-structure', difficulty: 5, stimulus: 'Text 1: The repeated motif in the song likely identifies its composer because it appears in three signed works.', secondaryStimulus: 'Text 2: The motif was common in the region and appears in works by at least nine composers.', prompt: 'Which choice best describes how Text 2 relates to Text 1?', choices: ['It weakens the proposed attribution by showing that the evidence is not distinctive.', 'It confirms that only one composer used the motif.', 'It changes the subject from music to regional politics.', 'It proves the three signed works are forgeries.'], answer: 0, explanation: 'If many composers used the motif, its presence cannot strongly identify one composer.', traps: ['Supported', 'Opposite of Text 2', 'Both discuss music', 'No forgery evidence'] }),
  b({ id: 'cid-05', skillId: 'central-ideas-details', domain: 'information-ideas', difficulty: 2, stimulus: 'When a river floods naturally, it deposits nutrient-rich sediment on its banks. Levees reduce flooding, but they can also prevent this sediment from reaching farmland. Some farmers therefore use controlled openings that admit a limited amount of floodwater.', prompt: 'Which choice best states the main idea of the text?', choices: ['Controlled flooding can preserve a benefit of natural floods while limiting their reach.', 'Levees always increase soil nutrients.', 'Farmers use openings to keep all river water away.', 'Natural floods carry no useful material.'], answer: 0, explanation: 'The openings allow beneficial sediment-bearing water while controlling flooding.', traps: ['Supported', 'Contradicted', 'Opposite', 'Contradicted'] }),
  b({ id: 'cid-06', skillId: 'central-ideas-details', domain: 'information-ideas', difficulty: 5, stimulus: 'Researchers reading a medieval recipe initially interpreted one ingredient as a spice because its name resembles a modern spice term. Trade records from the same town, however, classify the ingredient with dyes, and residue in cooking vessels contains no trace of it. The recipe may describe coloring the cloth used to cover the dish rather than seasoning the food.', prompt: 'Which choice best states the main idea of the text?', choices: ['Evidence from multiple sources supports a new interpretation of an ambiguous recipe instruction.', 'Medieval cooks never used spices.', 'Trade records are always more reliable than recipes.', 'The residue proves the dish was not cooked.'], answer: 0, explanation: 'Linguistic, trade, and residue evidence together motivate a revised interpretation.', traps: ['Supported', 'Unsupported absolute claim', 'Overgeneralizes source reliability', 'The dish may still have been cooked'] }),
  b({ id: 'cet-05', skillId: 'command-evidence-textual', domain: 'information-ideas', difficulty: 3, stimulus: "Wall labels in sculpture galleries usually give a title, a date, and a material, a convention that saves space and keeps text from competing with the work itself. Curator Fionnuala Byrne noticed that visitors leaving the modern wing could recite an artist name and a decade yet say nothing about how an object had been made. For one exhibition she prepared two labels of identical size for the same bronze figure: one listed dates alone, while the other described the casting and finishing steps the artist had used. Byrne claims that visitors understand a sculpture better when its label describes the artist's process rather than only listing dates.", prompt: 'Which finding would most directly support the claim?', choices: ['Visitors who read process-focused labels gave more accurate explanations of the sculpture than visitors who read date-only labels.', 'Process-focused labels contained more words.', 'Some visitors did not read either label.', 'The sculpture was made over several years.'], answer: 0, explanation: 'The comparison directly tests label type against visitor understanding.', traps: ['Supported', 'Length alone does not measure understanding', 'Does not compare readers', 'Object history does not test labels'] }),
  b({ id: 'cet-06', skillId: 'command-evidence-textual', domain: 'information-ideas', difficulty: 5, stimulus: 'Two medieval chronicles of the same provincial revolt survive: one copied in the 1340s and long known to scholars, the other discovered in 2019 in a monastery library. The narratives run parallel for most of their length and even divide the events into the same episodes, but such agreement is weak evidence of dependence, since chroniclers working from a shared oral tradition often produced similar accounts. The question matters because a set of local customs appears in no other source. Philologist Tomas Kaczmarek argues that the newly found manuscript is a copy made from the earlier surviving manuscript rather than an independent version of the same events.', prompt: 'Which finding would most directly support the argument?', choices: ['The new manuscript repeats several unique copying errors found only in the earlier manuscript.', 'Both manuscripts discuss the same historical event.', 'The new manuscript uses dark ink.', 'The earlier manuscript has more pages.'], answer: 0, explanation: 'Shared unique errors strongly indicate direct copying rather than independent composition.', traps: ['Supported', 'Same topic does not show dependence', 'Ink color is irrelevant', 'Page count does not show copying'] }),
  b({ id: 'ceq-03', skillId: 'command-evidence-quantitative', domain: 'information-ideas', difficulty: 5, stimulus: 'A field station recorded air temperature at three forest sites on the same day, taking readings at a fixed morning, noon, and evening hour so that the measurements at each site could be compared directly. The sites differ in canopy cover: Site A stands in an open clearing, Site B beneath scattered trees, and Site C under a dense evergreen canopy. Sensors were mounted at the same height above the ground and shielded from direct sunlight, and no precipitation fell on the day of the survey. The readings come from a long-term monitoring program that has operated at all three sites since 2011. A researcher claims that Site C showed the most consistent temperature across the day.', table: { caption: 'Temperature by site', headers: ['Site', 'Morning', 'Noon', 'Evening'], rows: [['A', '14°C', '23°C', '16°C'], ['B', '17°C', '25°C', '18°C'], ['C', '19°C', '22°C', '20°C']] }, prompt: 'Which choice most effectively uses data from the table to support the claim?', choices: ['Site C ranged from 19°C to 22°C, a smaller range than Site A or Site B.', 'Site C had the highest morning temperature.', 'Every site was warmest at noon.', 'Site A rose 9°C from morning to noon.'], answer: 0, explanation: 'Consistency is measured by spread, and Site C has the smallest range.', traps: ['Supported', 'One time point does not show consistency', 'Shared pattern does not compare consistency', 'Describes Site A only'] }),
  b({ id: 'ceq-04', skillId: 'command-evidence-quantitative', domain: 'information-ideas', difficulty: 3, stimulus: 'Nitrate reaching a lake from surrounding farmland can accelerate algal growth, but the relationship is rarely proportional: beyond a certain point additional nitrate produces little further gain because another nutrient becomes limiting. Ecologist Sora Diallo grew samples of the same freshwater alga at four nitrate concentrations spanning the range measured in nearby waterways. Light, temperature, starting population, and experiment duration were identical for all samples, and each concentration was replicated in five separate vessels whose masses were averaged. Diallo claims that the largest measured gain in average algal mass occurred when nitrate concentration increased from 2 to 4 milligrams per liter.', plot: { kind: 'line', caption: 'Average algal mass after fourteen days', xLabel: 'Nitrate concentration (mg/L)', yLabel: 'Average algal mass (mg)', points: [{ x: 0, y: 8 }, { x: 2, y: 11 }, { x: 4, y: 19 }, { x: 6, y: 21 }] }, prompt: "Which choice most effectively uses data from the graph to support Diallo's claim?", choices: ['Average mass rose 8 mg from 2 to 4 mg/L, compared with gains of 3 mg and 2 mg across the other measured intervals.', 'Average mass was 21 mg at 6 mg/L, which was 2 mg above the value measured at 4 mg/L.', 'Average mass increased at all three measured intervals, rising from 8 mg at 0 mg/L to 21 mg at 6 mg/L.', 'Average mass was 11 mg at 2 mg/L and 19 mg at 4 mg/L, so both values exceeded the starting mass.'], answer: 0, explanation: 'The 8 mg gain from 2 to 4 mg/L is larger than the 3 mg and 2 mg gains across the other adjacent intervals.', traps: ['Supported', 'Identifies the highest endpoint rather than the largest interval gain', 'Shows an overall rise without comparing interval sizes', 'Gives the relevant endpoints but does not compare the gain with other intervals'] }),
  b({ id: 'ceq-05', skillId: 'command-evidence-quantitative', domain: 'information-ideas', difficulty: 4, stimulus: 'Sand temperature governs much of what happens inside a sea turtle nest, from the rate of embryonic development to the proportion of eggs that hatch at all. Marine biologist Elena Park monitored nests on six beaches chosen because they had similar shade cover, grain size, and moisture, leaving average sand temperature as the principal difference among them. She grouped nests into one-degree temperature bands and plotted the mean hatching success for each band, so that every point represents many nests rather than a single clutch. Park claims that the observations show a negative association between sand temperature and hatching success across the measured range.', plot: { kind: 'scatter', caption: 'Sand temperature and sea turtle hatching success', xLabel: 'Average sand temperature (°C)', yLabel: 'Hatching success (%)', points: [{ x: 26, y: 88 }, { x: 27, y: 84 }, { x: 28, y: 78 }, { x: 29, y: 71 }, { x: 30, y: 63 }, { x: 31, y: 55 }] }, prompt: "Which choice most effectively uses data from the graph to support Park's claim?", choices: ['As average sand temperature rose from 26°C to 31°C, hatching success fell from 88% to 55%, with each plotted increase in temperature paired with a lower success rate.', 'Hatching success was 88% at 26°C, the lowest average sand temperature included in the observations.', 'The 29°C temperature band had 71% hatching success, a value between the results for the 28°C and 30°C bands.', 'Average sand temperature differed by 5°C between the coolest and warmest bands, while every band had hatching success above 50%.'], answer: 0, explanation: 'The choice describes the consistent downward pattern in hatching success as temperature rises, directly supporting a negative association.', traps: ['Supported', 'Reports one endpoint without showing an association', 'Reports the ordering of three points without describing the full relationship', 'Describes the ranges but not the direction linking the variables'] }),
  b({ id: 'ceq-06', skillId: 'command-evidence-quantitative', domain: 'information-ideas', difficulty: 5, stimulus: 'A photodiode does not respond equally to every color of light; its sensitivity curve is a property of the semiconductor from which it is made, and manufacturers publish it so that engineers can choose a suitable device. Engineers testing one such sensor illuminated it at five wavelengths while holding the brightness and the distance of the source constant, and reported the resulting signal as a percentage of the maximum the device can produce. Each wavelength was produced by a narrow-band filter and measured three times. They claim that within the measured range, the sensor response peaks near 550 nanometers rather than simply increasing as wavelength increases.', plot: { kind: 'dot', caption: 'Sensor response at selected wavelengths', xLabel: 'Wavelength (nm)', yLabel: 'Sensor response (%)', points: [{ x: 450, y: 20 }, { x: 500, y: 49 }, { x: 550, y: 83 }, { x: 600, y: 60 }, { x: 650, y: 31 }] }, prompt: "Which choice most effectively uses data from the graph to support the engineers' claim?", choices: ['Response reached 83% at 550 nm but was lower at both 500 nm and 600 nm, then fell further at 650 nm.', 'Response increased by 29 percentage points from 450 nm to 500 nm and by 34 points from 500 nm to 550 nm.', 'Response was 20% at 450 nm, the smallest value among the five wavelengths that the engineers measured.', 'Response was 60% at 600 nm and 31% at 650 nm, a decrease of 29 percentage points across that interval.'], answer: 0, explanation: 'The response is highest at 550 nm and lower on both sides, which supports a peak rather than a continuing increase.', traps: ['Supported', 'Shows the rise toward 550 nm but not the lower response beyond it', 'Identifies the minimum without locating the peak', 'Shows a decline after 600 nm but omits the peak and the rise toward it'] }),
  b({ id: 'inf-05', skillId: 'inferences', domain: 'information-ideas', difficulty: 3, stimulus: 'Participants in a laboratory memory task studied twenty pairs of unrelated words and were later asked to supply the second word of each pair. Recall was equally accurate in silence and against steady mechanical noise. It declined only when the background contained changing speech, that is, recorded conversation whose words and rhythm shifted continuously.', prompt: 'Which choice most logically completes the text?', choices: ['is disrupted by variation and linguistic content in background sound rather than by sound itself', 'is prevented entirely whenever any sound is present during study', 'is reliably better in silence than under every other condition', 'depends on participants having understood each background conversation'], answer: 0, explanation: 'Steady noise left recall unchanged while changing speech reduced it, so variation and linguistic content, not sound alone, account for the disruption.', traps: ['Supported', 'Contradicted by accurate recall under steady noise', 'Contradicted by equal recall in silence and steady noise', 'Comprehension of the background speech was not measured'] }),
  b({ id: 'inf-06', skillId: 'inferences', domain: 'information-ideas', difficulty: 5, stimulus: 'A coastal shorebird has shifted its nesting dates roughly nine days earlier over the past two decades. Ornithologist Bogdan Petrescu modeled the shift against both calendar year and average spring temperature at the colony. Year alone predicted the trend well, but once spring temperature was entered into the model, calendar year no longer showed any relationship to nesting date.', prompt: 'Which choice most logically completes the text?', choices: ['are better explained by warming springs than by the passage of calendar years itself', 'occur without regard to the temperatures the birds encounter at the colony', 'show that the calendar year determines how warm a given spring becomes', 'are matched by comparable shifts in every other coastal species'], answer: 0, explanation: 'Calendar year loses its relationship to nesting date once temperature is included, which points to warming springs as the underlying factor.', traps: ['Supported', 'Contradicted by the temperature relationship', 'Reverses the explanation', 'Overgeneralizes to species that were not studied'] }),
  b({ id: 'inf-07', skillId: 'inferences', domain: 'information-ideas', difficulty: 5, stimulus: 'In an experiment on how images shape belief, readers judged the credibility of ambiguous statements about unfamiliar scientific and historical subjects. Statements paired with a photograph clearly related to their content were rated more credible than the same statements presented without any illustration. Pairing those statements with visually striking but topically unrelated photographs produced no such increase.', prompt: 'Which choice most logically completes the text?', choices: ['are influenced by how relevant an accompanying image seems rather than by its visual appeal alone', 'find the claim more credible whenever any photograph accompanies it', 'rated the unrelated photographs lower in visual quality than the relevant ones', 'are right to treat a relevant photograph as proof that the claim is accurate'], answer: 0, explanation: 'Only relevant photographs raised credibility although both sets were rated similarly for quality, which isolates relevance from visual appeal.', traps: ['Supported', 'Contradicted by the unrelated-photograph condition', 'Contradicted by the similar quality ratings', 'Credibility judgments do not establish truth'] }),
  b({ id: 'bnd-08', skillId: 'boundaries', domain: 'standard-english', difficulty: 2, stimulus: 'The artist used one unusual material ____ paper made from seaweed.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: [':', ',', ';', ''], answer: 0, explanation: 'A colon follows the complete clause and introduces the specific material.', traps: ['Supported', 'Comma is too weak', 'Semicolon cannot introduce a noun phrase', 'A boundary is needed'] }),
  b({ id: 'bnd-09', skillId: 'boundaries', domain: 'standard-english', difficulty: 3, stimulus: 'Solar panels covered the south roof ____ the north roof remained shaded by trees.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: [';', ',', ':', ''], answer: 0, explanation: 'A semicolon correctly joins the two closely related independent clauses.', traps: ['Supported', 'Comma splice', 'The second clause is not an explanation of an announced idea', 'Missing boundary'] }),
  b({ id: 'bnd-10', skillId: 'boundaries', domain: 'standard-english', difficulty: 4, stimulus: 'The device, small enough to fit in a pocket ____ can measure particles in the air.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: [',', ';', ':', ''], answer: 0, explanation: 'The nonessential descriptive phrase begins after a comma and must close with another comma.', traps: ['Supported', 'Separates subject and verb with a semicolon', 'Separates subject and verb with a colon', 'Leaves the phrase unclosed'] }),
  b({ id: 'bnd-11', skillId: 'boundaries', domain: 'standard-english', difficulty: 5, stimulus: 'The team expected one outcome ____ that the untreated samples would decay first.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: [':', ';', ',', ''], answer: 0, explanation: 'The complete first clause announces an outcome, and the that clause specifies it.', traps: ['Supported', 'The second part is not an independent clause', 'Comma is not the correct introducing boundary', 'A boundary is needed'] }),
  b({ id: 'fss-08', skillId: 'form-structure-sense', domain: 'standard-english', difficulty: 2, stimulus: 'Each of the samples ____ labeled before the test began.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: ['was', 'were', 'have', 'being'], answer: 0, explanation: 'Each is singular and takes the singular verb was.', traps: ['Supported', 'Agrees with nearby samples instead of each', 'Wrong form and agreement', 'Incomplete verb'] }),
  b({ id: 'fss-09', skillId: 'form-structure-sense', domain: 'standard-english', difficulty: 4, stimulus: 'The study depended on collecting answers from participants in several districts on the same afternoon. Having completed the survey, ____ uploaded the responses.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: ['the responses', "the researchers' responses", 'the researchers', 'uploading the responses'], answer: 2, explanation: 'The researchers completed the survey, so that noun must immediately follow the opening modifier.', traps: ['Creates a dangling modifier', 'Creates a dangling modifier', 'Supported', 'Does not complete the sentence'] }),
  b({ id: 'fss-10', skillId: 'form-structure-sense', domain: 'standard-english', difficulty: 5, stimulus: 'The data suggest that the treatment, rather than the two control conditions, ____ responsible for the change.', prompt: 'Which choice completes the text so that it conforms to the conventions of Standard English?', choices: ['is', 'are', 'were being', 'have been'], answer: 0, explanation: 'The subject treatment is singular. The interrupting rather than phrase does not change agreement.', traps: ['Supported', 'Proximity agreement with conditions', 'Wrong agreement and unnecessary progressive form', 'Wrong agreement'] }),
  b({ id: 'rhs-06', skillId: 'rhetorical-synthesis', domain: 'expression-ideas', difficulty: 2, stimulus: 'While researching a topic, a student has taken the following notes.\n• Composer Elia Song wrote the ensemble piece River Glass.\n• The score calls for percussion instruments only.\n• Performers also tap the wooden stage floor with their palms.\n• The piece lasts about eleven minutes.\nThe student wants to introduce the work and its unusual sound sources.', prompt: 'Which choice most effectively uses relevant information from the notes?', choices: ["Elia Song's River Glass creates sound with percussion instruments and performers tapping the stage floor.", 'River Glass is a composition by Elia Song.', 'Stage floors are sometimes made of wood.', 'The performers play a piece and stand on a stage.'], answer: 0, explanation: 'The sentence identifies the work and foregrounds both unusual sources of sound.', traps: ['Supported', 'Omits the requested feature', 'Not from the notes', 'Too general'] }),
  b({ id: 'rhs-07', skillId: 'rhetorical-synthesis', domain: 'expression-ideas', difficulty: 4, stimulus: 'While researching a topic, a student has taken the following notes.\n• A 2018 survey counted 42 butterfly species in Harrow Meadow Park.\n• A 2025 survey counted 57 species in the same park.\n• Both surveys followed identical routes.\n• Both surveys were carried out in the same season.\nThe student wants to emphasize the change while making the comparison fair.', prompt: 'Which choice most effectively uses relevant information from the notes?', choices: ['Using the same routes and season, surveys counted 42 butterfly species in 2018 and 57 in 2025.', 'The park had butterflies in both 2018 and 2025.', 'The 2025 survey counted 57 butterfly species in the park.', 'Survey routes can affect how many butterflies are seen.'], answer: 0, explanation: 'The sentence reports the increase and the matched method that supports comparison.', traps: ['Supported', 'Omits the size of the change', 'Omits the baseline and matched method', 'General claim does not report results'] }),
  b({ id: 'rhs-08', skillId: 'rhetorical-synthesis', domain: 'expression-ideas', difficulty: 5, stimulus: 'While researching a topic, a student has taken the following notes.\n• The common account credits a single lead engineer with the dam design.\n• Payroll records from the period list six draftspersons on the project.\n• Their notebooks contain calculations that appear in the final plan.\n• The lead engineer approved the completed design.\nThe student wants to qualify the common account without denying the lead engineer role.', prompt: 'Which choice most effectively uses relevant information from the notes?', choices: ['Although the lead engineer approved the dam design, payroll records and notebooks show that six draftspersons contributed calculations to the final plan.', 'Six draftspersons designed the dam without any lead engineer.', 'The lead engineer alone performed every calculation.', 'Payroll records list workers and notebooks contain calculations.'], answer: 0, explanation: 'The sentence preserves the lead approval role while adding evidence of substantial collaboration.', traps: ['Supported', 'Overcorrects and contradicts the notes', 'Repeats the account despite contrary evidence', 'Lists evidence without qualifying the account'] }),
  b({ id: 'trn-07', skillId: 'transitions', domain: 'expression-ideas', difficulty: 2, stimulus: 'The survey aircraft carries two instruments mounted inside a single housing. The camera records visible light. ____, a separate sensor records infrared radiation.', prompt: 'Which choice most logically completes the text?', choices: ['In addition', 'Instead', 'Therefore', 'Nevertheless'], answer: 0, explanation: 'The second sensor adds another type of recording.', traps: ['Supported', 'The infrared sensor does not replace the camera', 'No cause and result', 'No concession'] }),
  b({ id: 'trn-08', skillId: 'transitions', domain: 'expression-ideas', difficulty: 4, stimulus: 'Historians studying the coronation depend on a single damaged codex. The manuscript is incomplete. ____, its surviving pages contain the only known description of the ceremony.', prompt: 'Which choice most logically completes the text?', choices: ['Nevertheless', 'Similarly', 'For example', 'As a result'], answer: 0, explanation: 'The text remains valuable despite being incomplete, so concession is required.', traps: ['Supported', 'No similarity', 'The second sentence is not an example of incompleteness', 'Value is not caused by incompleteness'] }),
  b({ id: 'trn-09', skillId: 'transitions', domain: 'expression-ideas', difficulty: 5, stimulus: 'Retailers use statistical models to plan inventory months in advance. The model accurately predicts short-term demand. ____, its long-term forecasts become unreliable when consumer preferences shift.', prompt: 'Which choice most logically completes the text?', choices: ['By contrast', 'Consequently', 'For instance', 'Likewise'], answer: 0, explanation: 'Accurate short-term and unreliable long-term performance are contrasted.', traps: ['Supported', 'Long-term failure is not stated as a result of short-term accuracy', 'The second sentence is a contrasting case, not an example of accuracy', 'The outcomes differ'] }),
]

const stimulusAdditions: Record<string, string> = {
  'wic-01': 'Before the project, locating a single letter could require searching several boxes by hand. Now users can trace names, dates, and subjects through a searchable record before requesting the original documents.',
  'wic-02': 'The reading appeared in only one of four trials and conflicted with the established model. Because a loose connection might have caused it, the physicist checked every instrument before collecting a new series of measurements.',
  'wic-03': 'Visitors can still recognize the broad curve that once sheltered arriving trains, although the new roof uses narrow timber ribs and translucent panels. The reference is deliberate without being a literal copy.',
  'wic-04': 'The writer joined the party after its departure and left before it reached the interior. Later historians can compare the diary with supply lists and maps, but those sources cannot fill every gap in the daily record.',
  'wic-05': 'One map was drawn for sailors navigating close to land, whereas the other shows the entire bay for regional planning. When both are converted to the same projection, the apparent bends line up point for point.',
  'wic-06': 'At a funeral, for instance, the narrator reports a cup being washed and returned to a shelf, allowing the ordinary action to carry the grief. The prose trusts readers to register what the narrator never states directly.',
  'wic-07': 'Staff members previously copied each title, date, and shelf location into several separate forms. The new system transfers verified information automatically, reducing duplicate work while leaving final approval to a librarian.',
  'wic-08': 'Researchers first assumed that the specimens belonged to a single population. Microscopic examination, however, linked the tooth variation to wear patterns produced by distinct diets, changing how the fossils were classified.',
  'wic-09': 'National archives document the decrees themselves, whereas shop ledgers reveal how traders altered proposed rules during consultation. By placing those records together, the essay preserves the familiar narrative while making its causes less simple.',
  'wic-10': 'The hearth context alone cannot distinguish food that residents planted from food they gathered locally. Future evidence from storage patterns, field remains, or genetic change could support cultivation, but none is currently available.',
  'wic-11': 'Drafts in the composer archive show dozens of these small adjustments, often made after a rehearsal exposed an awkward emphasis. The surviving pages rarely contain the kind of extensive rewriting that would produce an entirely new movement.',
  'tsp-01': 'Water entering a mangrove stand must pass through a dense lattice of prop roots, and the drag those roots create weakens the current well before it reaches the shore. As fine mineral particles drop out of the slowing water, they accumulate in layers that raise the sediment surface a few millimeters each year. Coastal engineers studying eroding shorelines have begun measuring that accumulation directly, because a stand that gains elevation can keep pace with a rising sea while a bare beach cannot.',
  'tsp-02': 'Those models rested on the small size of the moon: a body that compact should have shed its internal heat long ago and settled into permanent stillness. The instruments, left behind by several missions, transmitted for years afterward and logged events whose depth and repetition ruled out meteorite strikes as the sole cause. Planetary scientists including Astrid Halvorsen now treat the record as a reason to revisit how long a small body can retain enough heat to keep deforming.',
  'tsp-03': 'The researchers therefore argue that apparent boldness may sometimes reflect sensitivity to food cues rather than a general willingness to investigate novelty. Their proposal matters because boldness is ordinarily treated as a stable disposition belonging to an individual animal. If the response depends on odor, then observations gathered near discarded food may considerably overstate how readily urban foxes explore unfamiliar objects in settings where nothing edible is present.',
  'tsp-04': 'The label reflects a classification assigned when the bowl entered the collection in 1904, on the basis of its painted interior and its recovery from a burial chamber. Microscopic traces of soot also appear in pores on the lower surface, although contamination during excavation cannot be ruled out. Taken together, the clues justify revising the label to acknowledge uncertainty rather than replacing one definite claim with another.',
  'tsp-05': 'Physicists can first calculate how an object would travel across the idealized surface and then reintroduce measured resistance in a second step. The difference between the two results shows precisely how much of the observed motion friction accounts for, which is far harder to determine when every influence is modeled at once. Critics sometimes object that no laboratory bench behaves this way, but the objection mistakes a deliberate simplification for an error of description.',
  'tsp-06': 'Circulating red blood cells absorb light strongly, so an animal that is otherwise see-through would still be betrayed by the color moving through its vessels. During daytime rest the frog concentrates almost all of those cells inside a liver wrapped in reflective crystalline tissue, and the surrounding limbs and body cavity transmit whatever light strikes them. A predator scanning the underside of a leaf therefore encounters far less contrast than the frog would otherwise present.',
  'tsp-07': 'The survey covered four hundred trees in a mixed woodland, scoring each trunk for roughness on a five-point scale and recording every lichen species within a fixed band above the ground. When the investigators compared trees of identical age, rough-barked individuals still supported markedly more species, and smooth old trunks resembled smooth young ones. Age remains a convenient indirect clue, but texture better explains where airborne spores can lodge and retain moisture.',
  'tsp-08': 'Divers swam fixed transects and identified every fish they saw, a procedure that depends entirely on how far the observer can see. A follow-up using anchored acoustic recorders detected several species that the divers had missed, especially during the cloudiest surveys. The result does not show that clarity has no biological effect; it shows why the original counts alone cannot establish one.',
  'ctc-01': 'Water surfaces and streamside plantings absorb energy that paved channels reflect back into the air, and evaporation from the exposed channel removes additional heat. Measurements beside daylighting projects in three cities recorded lower afternoon temperatures during the first summer after construction.',
  'ctc-02': 'The marks are too regular to have resulted from accidental damage, and each fifth line is cut slightly longer than the four preceding it. Comparable tally systems from neighboring sites use the same visual break to help a reader recognize quantities quickly.',
  'ctc-03': "Even when individual word choices must shift, recurring end sounds preserve the pattern of expectation and release that shapes the reader's experience of the original lines. A version that discards those sounds may convey every literal statement while losing much of the artistic force of the poem.",
  'ctc-04': 'The decrease begins in the month when the older sodium lamps were replaced and continues steadily across the following year. Because the same pattern appears in several districts that adopted the program at different times, analysts attribute it to the policy rather than to a single damaged fixture or an unusually cloudy season.',
  'ctc-05': 'A typical daily commute in the region ran close to an hour in each direction, and workers who stopped making that trip described their mornings as less rushed. Advocates argue that removing a fixed daily obligation makes health-promoting routines easier to begin and sustain, even when total working hours stay the same.',
  'ctc-06': 'Its interval pattern is unusual within the surviving collection, and in each of the signed pieces it arrives immediately before the refrain, always in the same voice. On that basis the scholar treats the resemblance as a kind of musical signature rather than as a general feature of the period style.',
  'cid-01': 'Pigment cells beneath the surface expand or contract within a fraction of a second, and muscular papillae can raise the skin into ridges resembling algae. Some displays travel as waves across the body, while others appear only around the eyes, and their timing shifts according to whether another animal approaches or retreats.',
  'cid-02': 'Rice husk ash is a by-product of milling, and replacing part of the cement in a brick with it lowers both cost and waste. Adding more of it, however, changes how water binds within the mixture as the brick cures, so an environmental advantage does not guarantee greater strength.',
  'cid-03': 'Several sequences proved twice as long as their published descriptions indicated. Older collections made with narrow-band equipment may therefore hold more information than their catalog entries suggest, and Velez urges archives to preserve raw audio files because later processing can sometimes recover signals that the original playback systems discarded.',
  'cid-04': 'Editors of the period preferred novelty, so a naturalist recording the same meadow each week had little reason to expect publication. One surviving notebook lists the first flowering date of a single plant every April from 1912 through 1938, a sequence that now lets ecologists compare present timing against conditions recorded long before systematic monitoring began.',
  'cid-05': 'The openings are gated structures built into the levee and are operated only while the river runs high enough to carry suspended silt; they are closed again well before water can approach houses or roads. The practice demands careful timing, but measurements taken across several seasons show that the deposited silt can replace a portion of the fertilizer growers would otherwise purchase.',
  'cid-06': 'A second copy of the instructions places the disputed term beside a verb normally used for soaking textiles. No single clue settles the wording, but the linguistic, commercial, and chemical evidence all point away from the once-standard culinary reading.',
  'inf-01': 'The gas taken in overnight is stored as an organic acid and released the following morning inside cells whose pores have already closed, so photosynthesis continues in full sun without further exposure. Botanist Rania Haddad, who tracked gas exchange in a rocky basin across an entire summer, concluded that the timing of pore opening ______',
  'inf-02': 'Staff compared the twelve months before the move with the twelve months after and adjusted both totals for the seasonal rise and fall in borrowing. No lending rule changed during that period: the collection schedule, the length of a standard loan, and the fine structure all remained as they had been. The pattern therefore suggests that ______',
  'inf-03': 'Adult body mass was also similar in every condition, which makes it unlikely that the shift in timing was produced by widespread developmental failure among the warm-reared insects. Watanabe cautions that the chambers spanned a narrow range of temperatures, yet within that range the results indicate that temperature ______',
  'inf-04': 'The two kinds of recording were matched for loudness and duration, and every participant had heard each melody during training, so the later task measured recognition across a change in performance rather than prior familiarity with particular tunes. For these listeners, then, recognition appears to have ______',
  'inf-05': 'All three conditions were presented at the same volume, and participants completed an identical number of trials in each. The recorded conversation consisted of sentences on unfamiliar subjects, which makes it improbable that better memory for their content explains the difference. Psychologist Naledi Motaung concludes that performance on this task ______',
  'inf-06': 'Petrescu also accounted for habitat quality and for the age structure of the breeding population, neither of which altered the result. In years with similar spring temperatures the birds nested at similar times, even when those years lay far apart in the record, so the earlier nesting dates ______',
  'inf-07': 'Image conditions were assigned at random, and a separate group of participants rated all of the photographs without seeing any statements; the two sets received similar marks for visual quality. Because appeal was held roughly equal while relevance varied, the results suggest that readers assessing an ambiguous claim ______',
  'bnd-01': 'The contrast is most visible after several nights below freezing. Researchers monitoring oxygen levels sample both the still ice-covered basin and the narrow channel where water continues to flow.',
  'bnd-02': 'Participants receive the same materials at every worktable so that differences in equipment do not affect the finished models. Instructors check the sets before each session begins.',
  'bnd-03': 'A loose cable had allowed electrical noise to enter the readings. Once the connection was secured, the second trial produced the stable signal predicted by the calibration model.',
  'bnd-04': "Its author's identity remained unknown for another decade, even as reviewers praised the book's distinctive narrative voice. A signed letter discovered later finally linked the work to novelist Mara Bell.",
  'bnd-05': 'Tracking tags show that most individuals remain for less than a day before continuing south. On colder weeks, when insect activity is low, many birds bypass the site entirely.',
  'bnd-06': 'Coins from the same period are common near coastal markets. This one, by contrast, was recovered far inland along a route previously thought to have been abandoned centuries earlier.',
  'bnd-07': 'An earlier version protected the habitat by moving the access road, but that change would have added months to the project. The adopted plan reroutes drainage instead.',
  'bnd-08': 'The translucent sheets contain visible plant fibers and become slightly flexible in humid air. Rather than hiding those qualities, the artist used them to suggest the movement of ocean plants.',
  'bnd-09': 'The difference was intentional: neighboring buildings blocked afternoon light from the northern side. Designers placed battery equipment there instead of installing panels that would operate inefficiently.',
  'bnd-10': 'Its miniature pump draws a measured air sample across a replaceable filter. A connected phone then displays an estimate of particle concentration within seconds.',
  'bnd-11': 'Based on earlier studies, the researchers believed the protective coating would slow deterioration in every treated group. Their prediction specified how the comparison should unfold over the following month.',
  'fss-01': 'The images document camps, equipment, and landscapes that do not appear in the published expedition account. Conservators recently digitized the fragile plates so that researchers can examine them without handling the originals.',
  'fss-02': "A brief failure during the previous event had interrupted the speaker's opening remarks. For this presentation, the crew performed one check early in the morning and another immediately before the audience entered.",
  'fss-03': 'Infrared light passed through the upper layer of pigment but reflected from carbon-based ink below it. The resulting scans allowed the team to reconstruct several words that no longer appeared to the naked eye.',
  'fss-04': 'One group measured the coastal samples, while the other analyzed material from inland sites. Combining the measurements allowed both groups to test the same regional hypothesis with a larger dataset.',
  'fss-05': 'The original survives only as a damaged photograph, while three copies were made before the surface deteriorated. Unfortunately, glare obscures the same final line in every surviving image.',
  'fss-06': 'Both materials were applied at the same thickness and exposed to identical cycles of heat and moisture. The earlier material therefore provides a controlled baseline for evaluating the new formulation.',
  'fss-07': 'Letters from the period show that the group selected poems, reviewed submissions, and corrected proofs together. Later biographies sometimes credited the best-known poet with work performed by the full editorial circle.',
  'fss-08': 'The researchers prepared eight glass tubes containing different concentrations of the compound. A waterproof code on each tube allowed observers to record results without knowing which concentration they were viewing.',
  'fss-09': 'They checked the entries for duplicates and removed names before saving the file. Only members of the research team had permission to open the secure database.',
  'fss-10': 'Measurements from both controls remained close to their starting values, whereas treated samples changed sharply after forty-eight hours. Replication with a second batch produced the same pattern.',
  'rhs-01': '• The conversion preserved the exterior clock and the stone entrance arch.\n• Reading rooms now occupy floors that once contained private offices.',
  'rhs-02': '• All varieties received the same irrigation schedule.\n• R7 yielded 14 percent more grain than the next-best variety.',
  'rhs-03': '• Recordings were made in the same month and at the same time of day.\n• Patel did not measure traffic volume directly.',
  'rhs-04': '• Both hulls were tested in comparable weather conditions.\n• The ferry maintained its usual crossing time after the refit.',
  'rhs-05': '• The pigment lies beneath the original varnish.\n• Later restoration could not have placed it under the original paint layer.',
  'rhs-06': '• Two percussion groups perform from opposite sides of the room.\n• No string or wind instruments appear anywhere in the score.',
  'rhs-07': '• Researchers recorded every species observed at least twice.\n• Neither survey estimated the number of individual butterflies present.',
  'rhs-08': "• The draftspersons worked under the lead engineer's direction.\n• Several of their calculations appear in the approved construction drawings.",
  'trn-01': 'Both groups were kept at the same temperature and watered on an identical schedule; the only planned difference in the trial was the color of their containers.',
  'trn-02': 'Water released from an upstream reservoir had collected in the low ground beyond the bend, and staff closed the northern loop until it drained.',
  'trn-03': 'Earlier materials had softened or cracked at operating temperature, and the substitution let the team meet the safety requirement without adding a heavy cooling layer.',
  'trn-04': 'Predators looking down from above may overlook the animal entirely when it rests among real foliage, particularly in a breeze that sets leaf and insect swaying together.',
  'trn-05': 'The translator describes these as two distinct obligations: retaining the movement of the argument and reproducing imagery that readers can grasp without extensive notes.',
  'trn-06': 'Each measurement combines light from millions of surface features, but comparing that combined signal at different points in the orbit can expose repeating annual patterns.',
  'trn-07': 'A dichroic filter directs the two wavelength ranges to different detectors, and software later aligns the recordings so that investigators can compare features invisible in one range with those clearly visible in the other.',
  'trn-08': 'Several leaves are missing from the middle, and water damage has erased lines near the binding, yet no other participant recorded the event in comparable detail.',
  'trn-09': 'Near-term estimates rest on recent purchasing patterns that usually hold for several weeks, whereas new products and changing tastes can break those relationships over longer periods.',
}

const secondaryStimulusAdditions: Record<string, string> = {
  'ctc-01': 'A comparison of eleven completed projects in the same climate zone found almost no additional cooling at sites already shaded by tall buildings, while exposed plazas changed substantially. Stream restoration should therefore be evaluated site by site and treated as one element of a broader design strategy rather than as a uniform intervention.',
  'ctc-02': 'Several decorated border fragments from the same site include longer marks at regular intervals even though those bands plainly do not represent inventories. Until the scratches on the tablet can be linked to quantities through their archaeological context, describing them as numerical records goes beyond the available evidence.',
  'ctc-03': 'A translator can recreate those shifts through line length, stress, or repetition without reproducing the original rhyme scheme. Sound matters, but fidelity to one sonic feature may come at the expense of the structure that guides a reader through the poem.',
  'ctc-04': 'Laboratory calibration shows that an unchanged streetlight would appear roughly 18 percent dimmer to the replacement instrument. The archive must therefore be corrected across the sensor transition before it can indicate whether brightness in the city itself actually fell.',
  'ctc-05': 'On average, exercise received only a small share of the recovered minutes, and some participants exercised less than they had before. A reduction in commuting creates an opportunity, but individual constraints and preferences determine what actually happens to the time.',
  'ctc-06': 'Regional teaching manuals from the same decades even print the sequence as a standard exercise for students. Because so many trained musicians would have known it, an attribution requires further evidence such as distinctive notation, documented provenance, or a record of performance history.',
}

