const upgradedBlueprints = [...blueprints, ...extraBlueprints].map((item) => {
  const addition = stimulusAdditions[item.id]
  const stimulus = item.skillId === 'rhetorical-synthesis'
    ? item.stimulus?.replace('\nThe student wants', `\n${addition}\nThe student wants`)
    : [item.stimulus, addition].filter(Boolean).join(' ')
  const storedChoiceUpgrade = choiceUpgrades[item.id]
  const sourceOrder = choiceUpgradeSourceOrder[item.id]
  const upgradedChoices = storedChoiceUpgrade && sourceOrder
    ? sourceOrder.map((index) => storedChoiceUpgrade[index])
    : storedChoiceUpgrade ?? item.choices
  return {
    ...item,
    stimulus,
    secondaryStimulus: [item.secondaryStimulus, secondaryStimulusAdditions[item.id]].filter(Boolean).join(' '),
    choices: upgradedChoices,
    plot: item.plot,
  }
})

export const readingQuestionBank: Question[] = upgradedBlueprints.map((item) => {
  const topic = skillById.get(item.skillId)
  const offset = [...item.id].reduce((sum, character) => sum + character.charCodeAt(0), 0) % 4
  const order = [0, 1, 2, 3].map((_, index) => (index + offset) % 4)
  const choices = order.map((originalIndex, index) => ({ id: letters[index], text: item.choices[originalIndex] }))
  const answerIndex = order.indexOf(item.answer)
  const misconceptionByChoice: Record<string, string> = {}
  const whyWrong: Record<string, string> = {}
  order.forEach((originalIndex, index) => {
    const trap = item.traps[originalIndex]
    misconceptionByChoice[letters[index]] = trap
    if (originalIndex !== item.answer) whyWrong[letters[index]] = trap + '. Recheck the exact claim and the relationship signaled in the text.'
  })
  return {
    id: item.id,
    section: 'rw',
    domain: item.domain,
    skillId: item.skillId,
    difficulty: item.difficulty,
    format: 'multiple-choice',
    stimulus: item.stimulus,
    secondaryStimulus: item.secondaryStimulus,
    table: item.table,
    plot: item.plot,
    prompt: item.prompt,
    choices,
    answer: letters[answerIndex],
    explanation: item.explanation,
    concept: topic?.description ?? '',
    whyWrong,
    misconceptionByChoice,
    estimatedSeconds: item.difficulty <= 2 ? 55 : item.difficulty === 3 ? 70 : 85,
    source: 'local-original',
  }
})
